insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'acids-bases', 'Acid–base reaction', 'In chemistry, an acid–base reaction is a chemical reaction that occurs between an acid and a base. It can be used to determine pH via titration. Several theoretical frameworks provide alternative conceptions of the reaction mechanisms and their application in solving related problems; these are called the acid–base theories, for example, Brønsted–Lowry acid–base theory. Their importance becomes apparent in analyzing acid–base reactions for gaseous or liquid species, or when acid or base character may be somewhat less apparent. The first of these concepts was provided by the French chemist Antoine Lavoisier, around 1776. It is important to think of the acid–base reaction models as theories that complement each other. For example, the current Lewis model has the broadest definition of what an acid and base are, with the Brønsted–Lowry theory being a subset of what acids and bases are, and the Arrhenius theory being the most restrictive. The Arrhenius theory describes an acid as a substance that increases the concentration of hydrogen ions (H3O+ or H+) in a solution. A base is a substance that increases the concentration of hydroxide ions (OH-) in a solution. However, Arrhenius''s definition only applies to substances that are in water.', 'Wikipedia: Acid–base reaction', 'https://en.wikipedia.org/w/index.php?title=Acid%E2%80%93base_reaction&oldid=1371091825', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'acids-bases' and body = 'In chemistry, an acid–base reaction is a chemical reaction that occurs between an acid and a base. It can be used to determine pH via titration. Several theoretical frameworks provide alternative conceptions of the reaction mechanisms and their application in solving related problems; these are called the acid–base theories, for example, Brønsted–Lowry acid–base theory. Their importance becomes apparent in analyzing acid–base reactions for gaseous or liquid species, or when acid or base character may be somewhat less apparent. The first of these concepts was provided by the French chemist Antoine Lavoisier, around 1776. It is important to think of the acid–base reaction models as theories that complement each other. For example, the current Lewis model has the broadest definition of what an acid and base are, with the Brønsted–Lowry theory being a subset of what acids and bases are, and the Arrhenius theory being the most restrictive. The Arrhenius theory describes an acid as a substance that increases the concentration of hydrogen ions (H3O+ or H+) in a solution. A base is a substance that increases the concentration of hydroxide ions (OH-) in a solution. However, Arrhenius''s definition only applies to substances that are in water.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'acids-bases', 'Acid–base reaction: Historic development', 'The concept of an acid–base reaction was first proposed in 1754 by Guillaume-François Rouelle, who introduced the word "base" into chemistry to mean a substance which reacts with an acid to give it solid form (as a salt). Bases are mostly bitter in nature.', 'Wikipedia: Acid–base reaction', 'https://en.wikipedia.org/w/index.php?title=Acid%E2%80%93base_reaction&oldid=1371091825', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
